style.css:
@-moz-document domain("canva.com") {
:root{
  /* Theme */
  --bg-1: rgba(18,20,24,0.96);        /* main page background */
  --bg-2: rgba(255,255,255,0.04);     /* panel backgrounds / cards */
  --glass: rgba(255,255,255,0.06);    /* frosted glass */
  --accent: #6EE7B7;                  /* accent color (green mint) */
  --muted: #9aa4b2;                   /* muted text */
  --text: #e6eef6;                    /* primary text */
  --radius: 12px;                     /* border radius for panels */
  --shadow: 0 8px 24px rgba(0,0,0,0.6);
  --ui-gap: 10px;                     /* spacing */
  --font-sans: "Inter", "Segoe UI", Roboto, Arial, sans-serif;
  --ui-scale: 1;                      /* increase to scale UI (e.g. 1.05) */
}

/* Global reset for override */
html, body, #root, .app-root, .editor, .canva-app {
  background: linear-gradient(180deg, var(--bg-1), rgba(8,10,12,0.95)) !important;
  color: var(--text) !important;
  font-family: var(--font-sans) !important;
  -webkit-font-smoothing: antialiased !important;
  transform-origin: top left;
  transform: scale(var(--ui-scale));
}

/* Make main panels glassy and rounded */
header, nav, footer,
.sidebar, .left-sidebar, .right-sidebar,
[data-testid="sidebar"], [data-testid="tools-panel"],
[role="toolbar"], .topbar, .app-bar, .editor-controls {
  background: linear-gradient(180deg, rgba(255,255,255,0.02), var(--glass)) !important;
  border-radius: var(#00FF00) !important;
  box-shadow: var(#00FF00) !important;
  border: 1px solid rgba(255,255,255,0.035) !important;
  padding: calc(var(--ui-gap) * 0.6) !important;
}

/* Canvas area: bigger, centered, subtle border */
.editor-canvas, .canvas-container, [data-testid="canvas"] {
  background: linear-gradient(180deg, rgba(255,255,255,0.015), rgba(0,0,0,0.06)) !important;
  border-radius: calc(var(--radius) * 1.25) !important;
  padding: 16px !important;
  margin: 18px auto !important;
  box-shadow: 0 20px 60px rgba(0,0,0,0.7) inset, 0 12px 40px rgba(0,0,0,0.5) !important;
}

/* Target toolbar icons and give accent hover */
button, [role="button"], .btn, .toolbar-button {
  transition: transform .12s ease, box-shadow .12s ease, background-color .12s ease;
  border-radius: 10px !important;
  color: var(--text) !important;
  background: transparent !important;
}
button:hover, [role="button"]:hover, .toolbar-button:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 20px rgba(0,0,0,0.45);
  background: linear-gradient(180deg, rgba(255,255,255,0.012), rgba(255,255,255,0.02)) !important;
  outline: none !important;
}
button:focus, [role="button"]:focus { box-shadow: 0 0 0 3px rgba(110,231,183,0.14) !important; }

/* Accent color for active / selected items */
[aria-pressed="true"], .is-active, .selected, .active, [data-active="true"] {
  box-shadow: 0 6px 18px rgba(110,231,183,0.14) !important;
  border: 1px solid rgba(110,231,183,0.20) !important;
  background: linear-gradient(180deg, rgba(110,231,183,0.04), rgba(110,231,183,0.01)) !important;
}

/* Typography tweaks */
h1, h2, h3, .title, .heading {
  color: var(--text) !important;
  letter-spacing: -0.01em;
}
p, span, .label, .text, input, textarea {
  color: var(--text) !important;
  opacity: 0.95;
}
.small, .muted, .helper-text { color: var(--muted) !important; }

/* Make cards and suggestions slightly larger with comfortable padding */
.card, .menu, .panel, [data-testid="results-card"] {
  padding: 14px !important;
  border-radius: calc(var(--radius) - 2px) !important;
  background: linear-gradient(180deg, rgba(255,255,255,0.01), rgba(255,255,255,0.02)) !important;
  border: 1px solid rgba(255,255,255,0.03) !important;
}

/* Reduce clutter: smaller thumbnails / badges */
img, svg.icon, .thumbnail, .badge {
  filter: saturate(0.98) contrast(1.02);
  opacity: 0.95;
  border-radius: 8px;
}

/* Smooth scrollbar (modern browsers) */
*::-webkit-scrollbar { width: 10px; height: 10px; }
*::-webkit-scrollbar-track { background: transparent; }
*::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.04));
  border-radius: 10px;
  border: 2px solid rgba(0,0,0,0.12);
}

/* Floating quick actions — subtle elevation */
[role="dialog"], .modal, .popup, .floating-panel {
  background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01)) !important;
  border-radius: calc(var(--radius) + 4px) !important;
  box-shadow: 0 30px 80px rgba(0,0,0,0.75) !important;
}

/* Subtle watermark removal (visual only) - *use carefully* */
/* If a local element shows helper watermark text you don't like, this hides small UI hints.
   Uncomment if it targets only non-essential overlays */
/*
[aria-label*="Watermark"], .watermark, .tip-overlay, .help-text {
  display: none !important;
}
*/

/* Optional: hide left sidebar for extra canvas space
   Uncomment and adjust selector if your Canva shows a left sidebar with class .left-sidebar or data-testid "sidebar" */
/*
.left-sidebar, .sidebar, [data-testid="sidebar"] {
  display: none !important;
}
*/

/* Optional: hide top header bar to maximize canvas
   Uncomment if you want the top nav hidden */
 /*
header, .topbar, .app-header {
  display: none !important;
}
*/

/* Ensure buttons and inputs remain legible on dark background */
input, textarea, select, .input, .search-box {
  background: rgba(255,255,255,0.02) !important;
  border: 1px solid rgba(255,255,255,0.03) !important;
  color: var(--text) !important;
  padding: 8px 10px !important;
  border-radius: 8px !important;
}

/* Small screens: scale back UI-scale so interface fits */
@media (max-width: 1000px) {
  :root { --ui-scale: 0.95; }
  .editor-canvas, .canvas-container { margin: 10px !important; padding: 10px !important; }
}

/* Final safety: force readable contrast for text on any background */
*[style*="background"], *[style*="background-color"] {
  color: var(--text) !important;
  text-shadow: 0 1px 0 rgba(0,0,0,0.6);
}

/* End of style */
}
